// Normalize the downloaded Product Card image mimetype so OpenAI /v1/images/edits accepts it.
// CJ's CDN serves JPEG bytes labelled 'image/jpg' (non-standard); OpenAI accepts only
// image/jpeg, image/png, image/webp. We correct the label/filename only; bytes are unchanged.
const items = $input.all();
for (const item of items) {
  const b = item.binary && item.binary.source;
  if (!b) continue;
  const mt = String(b.mimeType || '').toLowerCase();
  if (mt === 'image/png') {
    b.mimeType = 'image/png'; b.fileExtension = 'png'; b.fileName = 'product.png';
  } else if (mt === 'image/webp') {
    b.mimeType = 'image/webp'; b.fileExtension = 'webp'; b.fileName = 'product.webp';
  } else {
    // image/jpg, image/jpeg, or any non-canonical JPEG label -> canonical image/jpeg
    b.mimeType = 'image/jpeg'; b.fileExtension = 'jpeg'; b.fileName = 'product.jpeg';
  }
}
return items;
